from pathlib import Path
from decimal import Decimal, localcontext
import hashlib,json,math
import argparse
parser=argparse.ArgumentParser(description='Reconstruct source inputs only; no native, Wasm, fit or author-code execution.')
parser.add_argument('--output',type=Path,required=True)
args=parser.parse_args()
root=Path.cwd()
out=args.output;out.mkdir(parents=True,exist_ok=False)
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def write(name,obj):(out/name).write_text(json.dumps(obj,indent=2,allow_nan=False)+'\n')
model=json.loads((root/'models/hypoplastic-sand-igs97.json').read_text())
params={'p_ref':100000.0,'phi':math.radians(33.1),'hs':4000000000.0,'n':0.27,'ed0':0.677,'ec0':1.054,'ei0':1.212,'alpha':0.14,'beta':2.5,'R':0.0001,'mR':2.2,'mT':1.1,'beta_r':0.1,'chi':5.5}
h=[]
for precision in [80,120]:
 with localcontext() as c:
  c.prec=precision;h.append(float(Decimal('0.0001')/Decimal(3).sqrt()))
assert h[0].hex()==h[1].hex()
state={'sigma':[100000.0]*3+[0.0]*3,'e':0.975,'h':[h[0]]*3+[0.0]*3}
assert list(params)==list(model['parameters'])
assert [f['name'] for f in model['state']]==list(state)
for k,v in params.items():
 d=model['parameters'][k];assert d['min']<=v<=d['max'],k
sources=[]
for id,name,url,doi,pages,locators in [
 ('wichtmann-2016-part1','wichtmann-2016-part1.pdf','https://www.torsten-wichtmann.de/paper/2016-AG-data-base-part1.pdf','10.1007/s11440-015-0402-z',[4,5],['Section3.2, PDFp3: isotropic preparation and history initialization','Table2 and Figure4a,b, PDFp4: complete parameters and named TMD2 curves','Table3, PDFp5: TMD2 e0=.975, ID0=.21, p0=100kPa']),
 ('wichtmann-2019-comparison','wichtmann-2019-model-comparison.pdf','https://www.torsten-wichtmann.de/paper/journal/2019-SDEE-Check-constitutive-models.pdf','10.1016/j.soildyn.2019.05.001',[2,3,4],['Table1, PDFp3: 13 material constants and calibration sources','Section3, PDFp3: h_ii=-R/sqrt(3) for isotropic initial stresses','Figure3a,b, PDFp4: loose ID0=21%, p0=100kPa, full displayed axial-strain range0-25%'])]:
  path=root/'paper/results/sources'/name
  sources.append(dict(id=id,url=url,doi=doi,local_path=str(path),sha256=sha(path),bytes=path.stat().st_size,visually_reviewed_pdf_pages=pages,locators=locators,redistribution='not bundled; no redistribution permission inferred'))
write('sources.json',{'id':'kfs-tmd2-igs-published-sources-v1','date':'2026-11-01','review':'coordinator targeted primary-source review; independent scientific review pending','sources':sources,'web_checks':[{'url':'https://www.torsten-wichtmann.de/KFSDB-TMD.htm','finding':'Provider groups TMD1-5 as loose drained monotonic compression tests; no new response download.'},{'url':'https://soilmodels.com/download/incrementaldriver-zip/','finding':'Download page exposes login/free-download placeholder; no manual/package acquired.'},{'url':'https://www.pg.gda.pl/~aniem/an-liter.html','finding':'Web retrieval failed; not evidence of source nonexistence.'},{'url':'https://www.rz.uni-karlsruhe.de/~gn99/','finding':'Historical author route from Masin guide failed in web retrieval.'}]})
write('parameter-set.json',{'schema_version':'0.1','id':'kfs-wichtmann-2016-2019-hypoplastic-igs','model':model['id'],'material':'Karlsruhe fine sand','parameters':params,'material_parameter_count':13,'numerical_scale_parameters':['p_ref'],'source':{'url':sources[1]['url'],'doi':sources[1]['doi'],'locator':'Table1, author PDFp3; independently checked against2016Table2 PDFp4','unit_conversions':{'phi':'33.1 degrees to radians','hs':'4000 MPa to4000000000 Pa'},'source_column_mapping':'2016Table2 orders mT,mR;2019Table1 orders mR,mT. Values mapped by symbols, not column position.'},'status':'primary tables transcribed and visually cross-checked; independent review pending','claim':'Complete VW96 plus IGS parameter set; not a fit, base-law transfer, or validation result.'})
experimental=json.loads((root/'data/normalized/KFS-TMD2.json').read_text())
flat=state['sigma']+[state['e']]+state['h']
write('case.json',{'study_version':1,'id':'kfs-tmd2-wichtmann-2019-igs-reproduction-v1','status':'source_case_selected_execution_not_authorized_by_this_manifest','model':model['id'],'definition_path':'models/hypoplastic-sand-igs97.json','definition_sha256':sha(root/'models/hypoplastic-sand-igs97.json'),'parameter_set':'parameter-set.json','source_records':'sources.json','source_case':{'primary':'2019Figure3a,b loose21% curves','test_identity':'KFS-TMD2','identity_evidence':'2016Figure4a,b explicitly labelsTMD2/100kPa/.21;2016Table3 gives unique matching pressure/density pair;2019Figure3 gives the same loose pair.','reproduction_role':'published calibration-example reproduction; previously exposed development data, not held-out validation','model_scope':'3D tensorial rate law under zero-spin axisymmetric material-point loading; no finite-deformation capability claim'},'initial':{'policy':'published nominal initial state, not first measurement and not current model defaults','named_state':state,'flat_state':flat,'history_conversion':'Source tension-positive h_ii=-R/sqrt(3) becomes Atlas compression-positive +R/sqrt(3); off-diagonal Mandel components are zero.','history_binary64':h[0].hex(),'history_rounding':'Source exact decimal R=1e-4 divided by sqrt(3), independently rounded at80/120decimal digits with identical binary64 result.','stress_units':'Pa','void_ratio_source':'2016Table3 TMD2:0.975; rounded published datum, no uncertainty inferred','measured_initial_state_separate':experimental['initial']},'loading':{'protocol':'drained axisymmetric compression','atlas_protocol':1,'radial_effective_stress_Pa':100000.0,'spin':'zero','published_axial_strain_interval':[0.0,0.25],'physical_time':'not supplied or inferred for this rate-independent case','history':'initialize directly to published mobilized state; no guessed preconsolidation replay','strain_mapping_status':'OPEN: establish plotted axial/volume strain versus source driver input before constructing executable controls. Do not silently treat finite engineering strain as accumulated infinitesimal strain.'},'outputs':{'stress':'sigma_xx-sigma_yy, compression-positive, kPa in source plot','volumetric_strain':'source plotted eps_v, percentage points; mapping from engine accumulated strain remains open','comparison_grid':'must be fixed when source curves are digitized, before any candidate execution'},'prospective_numerics':{'origin':'project choices, not claimed author input-deck settings','settings':{'version':'incremental-settings-0.1','norm':'scaled_component_max','residual_tolerance':2e-10,'rate_tolerance':1e-6,'max_iterations':45,'max_depth':14,'max_substeps':20000,'max_backtracks':11},'outer_step_counts':[400,800,1600],'maximum_material_calls':3,'execution_order':'serial native only first; no new build or Wasm matrix in this source task','admission':'No numerical acceptance policy is frozen yet; source-curve digitization/uncertainty and strain mapping must precede runtime observations.'},'experimental_data':{'path':'data/normalized/KFS-TMD2.json','sha256':sha(root/'data/normalized/KFS-TMD2.json'),'raw_member_sha256':experimental['provenance']['member_sha256'],'source_url':experimental['provenance']['source_url'],'redistribution':'existing local research copy only; no measured rows copied into this packet'},'open_gates':['Exact source driver/plotted strain mapping over the full25% range','Independent published-model curve digitization and precision-derived comparison bounds','Author code/version and numerical procedure equivalence not established','Independent equation and scientific review','Clean-checkout source/data/build reproduction and measurement distribution review'],'not_performed':['new calibration','native or Wasm execution','new build','source-code execution','data reservation release','experimental validation','deployment']})
write('source-checks.json',{'id':'kfs-tmd2-published-source-checks-v1','complete_material_parameters':len(params)-1,'project_scaling_parameters':['p_ref'],'parameter_order_matches_current_definition':True,'all_parameters_within_current_declared_bounds':True,'state_field_order_matches_current_definition':True,'history_rounding_80_120digits_agrees':True,'history_norm_ratio_binary64':math.sqrt(sum(x*x for x in state['h']))/params['R'],'material_calls':0,'status':'input checks only; not an independent constitutive-law or numerical-path test'})
receipt=json.loads((out/'sources.json').read_text())
receipt['sources'][0].update(title='An experimental data base for the development, calibration and verification of constitutive models for sand with focus to cyclic loading. Part I: tests with monotonic loading and stress cycles',authors=['Torsten Wichtmann','Theodoros Triantafyllidis'],year=2016)
receipt['sources'][1].update(title='Inspection of three sophisticated constitutive models based on monotonic and cyclic tests on fine sand: Hypoplasticity vs. Sanisand vs. ISA',authors=['Torsten Wichtmann','William Fuentes','Theodoros Triantafyllidis'],year=2019)
write('sources.json',receipt)
case=json.loads((out/'case.json').read_text());case['status']='selected_pending_protocol_and_reference_freeze';write('case.json',case)
rows=[r for r in experimental['rows'] if 0<=r['axial_strain']<=.25]
e0=experimental['initial']['void_ratio']
write('data-coordinate-check.json',{'scope':'descriptive algebraic consistency check on already exposed TMD2 development observations; no error threshold or model score','experiment_sha256':sha(root/'data/normalized/KFS-TMD2.json'),'row_count_in_published_interval':len(rows),'last_observed_axial_strain_in_interval':rows[-1]['axial_strain'],'maximum_absolute_residuals':{'epsv_minus_(e0-e)/(1+e0)':max(abs(r['volumetric_strain']-(e0-r['void_ratio'])/(1+e0)) for r in rows),'epsv_minus_log((1+e0)/(1+e))':max(abs(r['volumetric_strain']-math.log((1+e0)/(1+r['void_ratio']))) for r in rows),'epsv_minus_eps1_minus_2eps3':max(abs(r['volumetric_strain']-r['axial_strain']-2*r['radial_strain']) for r in rows)},'interpretation':'The supplied volume channel is consistent with fractional volume change from void ratio, and reported radial strain follows the additive convention. These linked channels are not independent measurements. This does not establish the author driver axial-input or plotted simulation-volume convention.','numerical_experiment_calls':0})
